function formatCount(n,one,few,many){const a=n%10,b=n%100;return n+' '+(b>=11&&b<=14?many:a===1?one:a>=2&&a<=4?few:many);}
function formatTypes(t){return new Set(t.questions.map(q=>q.type)).size;}
