const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const norm=s=>String(s).toLowerCase().replace(/ё/g,'е').replace(/[^a-zа-я0-9]/g,'');
function evaluate(q,value){
 if(q.type==='written')return false;
 if(q.type==='short')return q.aliases.some(a=>q.answerMode==='set'?[...norm(a)].sort().join('')===[...norm(value)].sort().join(''):norm(a)===norm(value));
 if(q.type==='single'||q.type==='multi')return Array.isArray(value)&&value.length===q.answer.length&&q.answer.every(a=>value.includes(a));
 if(q.type==='match')return q.rows.every(r=>value[r.id]===r.answer);
 return Array.isArray(value)&&value.length===q.answer.length&&q.answer.every((a,i)=>value[i]===a);
}
function labelOf(q,id){return(q.options||q.items).find(o=>o.id===id)?.label||String(id);}
function answerText(q,value){
 if(q.type==='short'||q.type==='written')return value||'Ответ не введён';
 if(q.type==='match')return q.rows.map(r=>r.label+' → '+(value[r.id]||'Не выбрано')).join('\n');
 if(q.type==='order')return value.map((id,i)=>(i+1)+'. '+labelOf(q,id)).join('\n');
 return value.length?value.map(id=>labelOf(q,id)).join('\n'):'Ничего не выбрано';
}
function correctValue(q){if(q.type==='match')return Object.fromEntries(q.rows.map(r=>[r.id,r.answer]));return q.answer;}
function correctText(q){return(q.type==='short'||q.type==='written')?q.answer:answerText(q,correctValue(q));}
function setSection(label){document.getElementById('sectionLabel').textContent=label;}
function home(){setSection('Тренажёр ЕГЭ');app.innerHTML=`<section class="home-screen"><div class="hero home-hero"><span class="pill">Готовься в своём темпе</span><h1>Шаг за шагом.<br><span>К уверенному ответу.</span></h1><p class="muted">Выбери предмет, тему и тест. Используй подсказки, проверяй ответы и возвращайся к ошибкам.</p></div><div class="catalog-heading"><h2>Предметы ЕГЭ</h2><span class="muted">${TESTS.reduce((n,t)=>n+t.questions.length,0)} заданий</span></div><div class="subject-grid">${['russian','social','history'].map(subject=>{const list=TESTS.filter(t=>t.subject===subject),topics=new Set(list.map(t=>t.topic)).size;return `<button class="subject-card available" data-subject="${subject}"><span class="subject-top"><span class="subject-icon icon-${subject}">${subject==='russian'?'Аа':subject==='social'?'§':'⌛'}</span><span class="availability live">Можно проходить</span></span><h3>${SUBJECTS[subject]}</h3><p>${formatCount(topics,'тема','темы','тем')} · ${formatCount(list.length,'тест','теста','тестов')}<br>Подсказки и разбор ошибок</p><span class="subject-bottom"><span>${formatCount(list.reduce((n,t)=>n+t.questions.length,0),'задание','задания','заданий')}</span><span aria-hidden="true">→</span></span></button>`}).join('')}</div><div class="catalog-note"><span class="note-symbol">✦</span><p>Темы идут по порядку курса. Перемешивание вопросов можно включить перед тестом; варианты ответов перемешиваются. Развёрнутые задания — с образцами и честной самопроверкой.</p></div><p class="note">Карты и иллюстрации загружаются вместе с заданиями. Для работы сайта и открытия исходных изображений по ссылкам нужно подключение к интернету.</p></section>`;app.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>testList(b.dataset.subject));scrollToTop();}
function emptySubject(subject){const title=subject==='russian'?'Русский язык':'Обществознание';setSection(title);app.innerHTML=`<section class="empty-screen"><button class="back-link" id="backHome">← Все предметы</button><div class="card empty-card"><span class="subject-icon ${subject==='russian'?'icon-russian':'icon-social'}">${subject==='russian'?'Аа':'§'}</span><h1>${title}</h1><p class="muted">Здесь пока нет тестов.</p><p class="note">Можно выбрать историю: в этом разделе уже доступны два теста.</p><button class="primary" id="openHistory">Перейти к истории →</button></div></section>`;document.getElementById('backHome').onclick=home;document.getElementById('openHistory').onclick=()=>testList('history');scrollToTop();}
let catalogSection='course',catalogSubject='';
const SECTION_LABELS={course:'По курсу',database:'Полная база',trial:'Пробники'};
function testList(subject,section){subject=typeof subject==='string'?subject:currentSubject;if(catalogSubject!==subject){catalogSection='course';catalogSubject=subject;}if(section)catalogSection=section;currentSubject=subject;setSection(SUBJECTS[subject]);const all=TESTS.filter(t=>t.subject===subject),list=all.filter(t=>t.section===catalogSection),topics=[...new Set(list.map(t=>t.topic))];app.innerHTML=`<section class="history-screen"><button class="back-link" id="backHome">← Все предметы</button><div class="hero"><span class="pill">${SUBJECTS[subject]} · ЕГЭ</span><h1>Учись<br><span>по порядку.</span></h1><p class="muted">${catalogSection==='course'?'Доступные темы текущего курса StudyCats — в порядке уроков. Задания из полной базы сюда не подмешиваются.':catalogSection==='database'?'Дополнительная практика за весь учебный год. Нумерованные темы идут по порядку источника; смешанные задания размещены в конце.':'Пробные варианты по разным темам. Здесь могут встречаться ещё не изученные периоды.'}</p></div><div class="course-tabs" role="group" aria-label="Раздел заданий">${Object.entries(SECTION_LABELS).map(([id,label])=>`<button data-section="${id}" aria-pressed="${id===catalogSection}" class="${id===catalogSection?'primary':''}">${label} · ${all.filter(t=>t.section===id).reduce((n,t)=>n+t.questions.length,0)}</button>`).join('')}</div><p class="note">${formatCount(topics.length,'тема','темы','тем')} · ${formatCount(list.reduce((n,t)=>n+t.questions.length,0),'задание','задания','заданий')}. Каждый тест содержит задания только своей темы. В полной базе есть отдельная общая практика.</p><label class="sr" for="topicSearch">Поиск темы</label><input class="text-input topic-search" id="topicSearch" type="search" placeholder="Найти тему или тест…"><div id="topicCatalog">${topics.map((topic,step)=>`<section class="topic-group" data-topic="${escapeHTML(topic.toLowerCase())}"><h2 class="topic-heading"><span class="course-step">${String(step+1).padStart(2,'0')}</span>${escapeHTML(topic)}</h2><div class="test-grid">${list.filter(t=>t.topic===topic).map(t=>`<button class="test-card" data-test="${t.id}"><span class="test-card-top"><span class="test-number">${String(t.part).padStart(2,'0')}</span><span class="pill">${t.questions.some(q=>q.type==='written')?'Есть письменная практика':'Автопроверка'}</span></span><h2>${escapeHTML(t.cardTitle||(t.title.includes(' · Часть ')?'Часть '+t.part:'Практика по теме'))}</h2><p>${formatCount(t.questions.length,'задание','задания','заданий')} · подсказки · разбор ошибок</p><div class="test-features"><span>По порядку</span><span>Без таймера</span></div><span class="test-card-bottom">Открыть тест <span aria-hidden="true">→</span></span></button>`).join('')}</div>${incompleteHTML(subject,topic,catalogSection)}</section>`).join('')}</div><p class="muted" id="noTopics" ${topics.length?'hidden':''}>По этому запросу тем не найдено.</p>${pendingCount(subject)?`<button class="materials-link" id="subjectMaterials">Нужны материалы · ${pendingCount(subject)} заданий →</button>`:''}</section>`;document.getElementById('backHome').onclick=home;app.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>testList(subject,b.dataset.section));app.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>selectTest(b.dataset.test));document.getElementById('topicSearch').oninput=e=>{const value=e.target.value.trim().toLowerCase();let count=0;app.querySelectorAll('.topic-group').forEach(g=>{g.hidden=!g.dataset.topic.includes(value);if(!g.hidden)count++});document.getElementById('noTopics').hidden=Boolean(count)};if(document.getElementById('subjectMaterials'))document.getElementById('subjectMaterials').onclick=()=>materials(subject);scrollToTop();}
function incompleteHTML(subject,topic,section){return PENDING.filter(q=>q.subject===subject&&q.topic===topic&&q.section===section).map(q=>`<details class="card incomplete-question" data-missing="${q.sourceId}"><summary><strong>Ещё одно задание по этой теме · нужна иллюстрация</strong></summary><p class="note">Для этого задания в архиве не найдено исходное изображение. Проверка пока недоступна, чтобы не оценивать ответ по неподходящей картинке.</p><div class="rich-material">${q.bodyHtml}</div><p class="note">${escapeHTML(q.sourceLabel)}</p>${q.missingImages.map(u=>`<p><a href="${escapeHTML(u)}" target="_blank" rel="noopener noreferrer">Открыть исходную ссылку · ${escapeHTML(u.split('/').pop().slice(0,70))}</a></p>`).join('')}</details>`).join('');}
function selectTest(id){selectedTest=TESTS.find(t=>t.id===id);currentSubject=selectedTest.subject;catalogSubject=currentSubject;catalogSection=selectedTest.section;BANK=selectedTest.questions;intro();scrollToTop();}
function lessonVideoHTML(test){
 const entries=window.EGE_VIDEO_LESSONS?.byTest?.[test.id]||[];
 const links=entries.filter(item=>{try{const url=new URL(item.url);return url.protocol==='https:'&&['rutube.ru','kinescope.io'].includes(url.hostname);}catch{return false;}});
 if(!links.length)return '<p class="note lesson-videos-empty">Ссылка на видео по этой теме пока не найдена.</p>';
 return `<section class="card lesson-videos" aria-label="Видео по теме"><h2>Видео по теме</h2><p class="note">Перед практикой можно повторить материал. Просмотр по желанию.</p>${links.map(item=>`<p><a href="${escapeHTML(item.url)}" target="_blank" rel="noopener noreferrer">▶ ${escapeHTML(item.title)} — смотреть на ${new URL(item.url).hostname==='kinescope.io'?'Kinescope':'Rutube'} ↗</a></p>`).join('')}</section>`;
}
function intro(){setSection(subjectName()+' · '+selectedTest.period);app.innerHTML=`<section class="intro test-intro"><button class="back-link" id="toTests">← К темам предмета</button><div class="hero"><span class="pill">${escapeHTML(selectedTest.label)}</span><h1>${escapeHTML(selectedTest.title)}</h1><p class="muted">${escapeHTML(selectedTest.description)}</p>${lessonVideoHTML(selectedTest)}</div><div class="intro-grid"><div class="mini"><b>${BANK.length}</b><small>заданий</small></div><div class="mini"><b>${formatTypes(selectedTest)}</b><small>${formatCount(formatTypes(selectedTest),'формат','формата','форматов').replace(/^\d+ /,'')}</small></div><div class="mini"><b>∞</b><small>попыток</small></div></div><div class="card"><p>Выбирай варианты, устанавливай соответствия и решай задания. Для письменного ответа сначала открой образец, затем оцени полноту своего решения по критериям. После проверки — правильный ответ и объяснение. Нажми на иллюстрацию, чтобы увеличить её.</p><label class="shuffle-setting"><input type="checkbox" id="shuffleQuestions"> Перемешивать вопросы внутри этого теста</label><button class="primary" id="start">Начать тест →</button><p class="note">Без таймера. Один учебный балл за полностью верное задание. Письменные ответы отмечаются отдельно как самопроверка. Кнопка «Подсказка» даёт наводку и не влияет на результат.</p><details><summary>О материалах и проверке</summary><p>${escapeHTML(selectedTest.sourceNote)}</p><p>${escapeHTML(selectedTest.auditNote)}</p><p>${selectedTest.subject==='russian'?'Задания набраны текстом по материалам курса. Для орфографических упражнений после проверки показаны заполненные слова.': 'Текст и таблицы перенесены из материалов курса и базы. Доступные карты встроены в файл. Для письменных заданий предусмотрены образцы и самопроверка.'}</p><p>Проверяются все пары и полный набор выбранных вариантов. В коротком ответе не учитываются регистр, пробелы, дефисы и «ё/е». Допустимые названия и формы ответа заданы отдельно для каждого задания.</p><p>Это учебная тренировка. Оценка в конце рассчитывается по проценту правильных заданий и не является официальным баллом ЕГЭ.</p></details></div></section>`;document.getElementById('toTests').onclick=backToTests;document.getElementById('start').onclick=start;}
function start(){questions=document.getElementById('shuffleQuestions')?.checked?shuffle(BANK):BANK.slice();index=0;results=[];prepare();render();scrollToTop();}
function prepare(){const q=questions[index];locked=false;draft=q.type==='match'?{}:(q.type==='short'||q.type==='written')?'':[];optionOrder=shuffle(q.options||[]);rowOrder=(q.rows||[]).slice();eventOrder=shuffle(q.items||[]).map(e=>e.id);if(q.type==='order')draft=eventOrder.slice();}
function scrollToTop(){window.scrollTo({top:0,behavior:'auto'});}
function showMap(key){const d=document.getElementById('zoom');document.getElementById('zoomImage').src=IMAGES[key];if(d.showModal)d.showModal();else{d.setAttribute('open','');}}
function mapHTML(q){return q.image?`<button class="map-button" type="button" data-map="${q.image}" aria-label="Увеличить карту"><img src="${IMAGES[q.image]}" alt="Историческая карта для задания" loading="eager"><span class="map-caption">Нажмите, чтобы открыть карту крупнее</span></button>`:'';}
function sourceHTML(q){if(q.sourceLabel)return q.sourceLabel;return `Материал ${q.sourceOrder} · Фото ${q.src.map(n=>n<=100?'первая серия, '+n:'вторая серия, '+(n-100)).join('; ')}`;}
function referenceHTML(q){return (q.references||[]).map(r=>`<p><a href="${escapeHTML(r.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(r.title)}</a></p>`).join('');}
function render(){
 const q=questions[index],good=results.filter(r=>r.ok).length,bad=results.length-good;
 const names={single:'Один ответ',multi:'Выбор ответов',match:'Соответствие',order:'Хронология',short:'Короткий ответ',written:'Письменная практика'};
 const instructions={single:'Выберите один вариант, затем проверьте ответ.',multi:q.id.startsWith('russian-')?'Выберите все подходящие ряды. Лишний или пропущенный ряд означает ошибку.':'Выберите все верные варианты: их может быть один или несколько. Лишний или пропущенный вариант означает ошибку.',match:'Выберите ответ в каждой строке. Проверяются все пары.',order:'Перемещайте события стрелками ↑ и ↓. Сверху — самое раннее.',written:'Напишите ответ, откройте образец и самостоятельно проверьте все требования. Совпадение отдельных слов не считается проверкой смысла.',short:q.answerMode==='sequence'?'Введите цифры в нужном порядке. Порядок цифр важен.':'Введите '+(q.answer==='1237'?'полный год':/^(IX|XII|XIII)$/.test(q.answer)?'век цифрами или словом':String(q.answer||'').endsWith('-е')?'десятилетие':q.answer==='Оки'?'название реки': 'название, имя или ответ на вопрос')+', затем проверьте ответ.'};
 let controls='';
 if(q.type==='single'||q.type==='multi')controls='<div class="options">'+optionOrder.map(o=>`<label class="option" data-id="${o.id}"><input type="${q.type==='single'?'radio':'checkbox'}" name="answer" value="${o.id}"><span>${escapeHTML(o.label)}</span></label>`).join('')+'</div>';
 if(q.type==='short')controls='<label class="sr" for="shortAnswer">Ваш ответ</label><input id="shortAnswer" class="text-input" type="text" autocomplete="off" autocapitalize="sentences" spellcheck="false" placeholder="Ваш ответ">';
 if(q.type==='written')controls='<label class="sr" for="writtenAnswer">Ваш развёрнутый ответ</label><textarea class="text-input written-input" id="writtenAnswer" placeholder="Запиши свой ответ здесь…"></textarea>';
 if(q.type==='match')controls=`<table><thead><tr><th scope="col">Событие / элемент</th><th scope="col">Ваш ответ</th></tr></thead><tbody>${rowOrder.map(r=>`<tr><td><label for="${r.id}">${escapeHTML(r.label)}</label></td><td><select id="${r.id}" data-row="${r.id}"><option value="">Выбрать…</option>${optionOrder.map(s=>`<option value="${escapeHTML(s)}">${escapeHTML(s)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table>`;
 if(q.type==='order')controls='<div class="order-list" id="orderList"></div>';
 app.innerHTML=`<section class="quiz-screen"><button class="back-link" id="toTests">← К темам предмета</button><div class="topline"><strong>Вопрос ${index+1} из ${questions.length}</strong><span class="muted">${Math.round(results.length/questions.length*100)}%</span></div><div class="track" role="progressbar" aria-label="Пройдено заданий" aria-valuemin="0" aria-valuemax="${questions.length}" aria-valuenow="${results.length}"><div class="fill" style="width:${results.length/questions.length*100}%"></div></div><div class="stats"><div class="stat good"><b>${good}</b>Правильно</div><div class="stat bad"><b>${bad}</b>Ошибки</div><div class="stat"><b>${questions.length-results.length}</b>Осталось</div></div><article class="card"><div class="meta"><span class="pill">${q.topic}</span><span class="type">${names[q.type]}</span></div><h2 id="questionTitle">${escapeHTML(q.q)}</h2>${q.bodyHtml?`<div class="rich-material">${q.bodyHtml}</div>`:''}${q.context?`<div class="context">${escapeHTML(q.context)}</div>`:''}${mapHTML(q)}<p class="instruction">${instructions[q.type]}</p><fieldset id="answers" aria-labelledby="questionTitle">${controls}</fieldset><div class="hint-area"><button class="hint-toggle" type="button" id="hintToggle" aria-expanded="false" aria-controls="hintText">Подсказка</button><p class="hint-text" id="hintText" hidden>${escapeHTML(q.hint)}</p></div><div id="feedback" class="feedback" hidden role="status" aria-live="polite"></div><div class="actions"><button id="check" class="primary" disabled>Проверить ответ</button></div><details class="source"><summary>Исходный материал</summary>${escapeHTML(sourceHTML(q))}${referenceHTML(q)}</details></article></section>`;
 document.getElementById('toTests').onclick=backToTests;
 app.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>showMap(b.dataset.map));
 if(q.type==='single'||q.type==='multi')app.querySelectorAll('input').forEach(inp=>inp.onchange=()=>{if(locked)return;draft=[...app.querySelectorAll('input:checked')].map(i=>i.value);ready();});
 if(q.type==='short')document.getElementById('shortAnswer').oninput=e=>{if(!locked){draft=e.target.value;ready();}};
 if(q.type==='written')document.getElementById('writtenAnswer').oninput=e=>{if(!locked){draft=e.target.value;ready();}};
 if(q.type==='match')app.querySelectorAll('select').forEach(s=>s.onchange=()=>{if(!locked){draft[s.dataset.row]=s.value;ready();}});
 if(q.type==='order')renderOrder();
 document.getElementById('hintToggle').onclick=()=>{const text=document.getElementById('hintText'),button=document.getElementById('hintToggle');text.hidden=!text.hidden;button.setAttribute('aria-expanded',String(!text.hidden));button.textContent=text.hidden?'Подсказка':'Скрыть подсказку';};
 document.getElementById('check').onclick=check;if(q.type==='written')document.getElementById('check').textContent='Сравнить с образцом';ready();
}
function renderOrder(){const q=questions[index],list=document.getElementById('orderList');list.innerHTML=eventOrder.map((id,i)=>`<div class="order-row"><span class="order-num">${i+1}</span><span class="order-label">${escapeHTML(labelOf(q,id))}</span><span class="arrows"><button type="button" data-pos="${i}" data-dir="-1" aria-label="Поднять: ${escapeHTML(labelOf(q,id))}" ${i===0?'disabled':''}>↑</button><button type="button" data-pos="${i}" data-dir="1" aria-label="Опустить: ${escapeHTML(labelOf(q,id))}" ${i===eventOrder.length-1?'disabled':''}>↓</button></span></div>`).join('');list.querySelectorAll('button').forEach(b=>b.onclick=()=>{if(locked)return;const i=Number(b.dataset.pos),j=i+Number(b.dataset.dir);[eventOrder[i],eventOrder[j]]=[eventOrder[j],eventOrder[i]];draft=eventOrder.slice();renderOrder();ready();});}
function ready(){if(locked)return;const q=questions[index];let valid=(q.type==='short'||q.type==='written')?draft.trim().length>0:q.type==='match'?q.rows.every(r=>Boolean(draft[r.id])):q.type==='order'?true:draft.length>0;document.getElementById('check').disabled=!valid;}
function check(){if(locked)return;const b=document.getElementById('check');if(b.disabled)return;const q=questions[index];if(q.type==='written'){revealWritten();return;}locked=true;const value=JSON.parse(JSON.stringify(draft)),ok=evaluate(q,value);results.push({q,value,ok});document.getElementById('answers').disabled=true;
 if(q.type==='single'||q.type==='multi')app.querySelectorAll('.option').forEach(el=>{if(q.answer.includes(el.dataset.id))el.classList.add('correct');else if(value.includes(el.dataset.id))el.classList.add('wrong');});
 if(q.type==='short')document.getElementById('shortAnswer').classList.add(ok?'correct':'wrong');
 if(q.type==='match')q.rows.forEach(r=>{document.querySelector('select[data-row="'+r.id+'"]').classList.add(value[r.id]===r.answer?'correct':'wrong');});
 if(q.type==='order')app.querySelectorAll('.order-row').forEach((row,i)=>row.classList.add(value[i]===q.answer[i]?'correct':'wrong'));
 const f=document.getElementById('feedback');f.hidden=false;f.className='feedback '+(ok?'good':'bad');f.innerHTML=`<div class="verdict">${ok?'✓ Правильно':'✕ Неправильно'}</div><p class="answer"><b>Правильный ответ:</b><br>${escapeHTML(correctText(q))}</p><p>${escapeHTML(q.ex)}</p>`;
 const good=results.filter(r=>r.ok).length;app.querySelectorAll('.stat b')[0].textContent=good;app.querySelectorAll('.stat b')[1].textContent=results.length-good;app.querySelectorAll('.stat b')[2].textContent=questions.length-results.length;
 app.querySelector('.fill').style.width=results.length/questions.length*100+'%';app.querySelector('[role="progressbar"]').setAttribute('aria-valuenow',results.length);app.querySelector('.topline .muted').textContent=Math.round(results.length/questions.length*100)+'%';
 b.textContent=index===questions.length-1?'Посмотреть результат':'Следующий вопрос →';b.onclick=next;
 f.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function revealWritten(){const q=questions[index];locked=true;document.getElementById('answers').disabled=true;const f=document.getElementById('feedback');f.hidden=false;f.className='feedback self-review';f.innerHTML=`<div class="verdict">Самопроверка</div><p>Сопоставь свой текст со всеми требованиями. Допустимы другие верные формулировки и примеры.</p><div class="answer source-answer"><b>Образец / критерии:</b><br>${escapeHTML(q.rubric||q.ex)}</div><div class="self-actions"><button id="selfGood" type="button">Все требования выполнены</button><button id="selfBad" type="button">Нужно повторить</button></div>`;const b=document.getElementById('check');b.disabled=true;b.textContent='Сначала оцени свой ответ';document.getElementById('selfGood').onclick=()=>markWritten(true);document.getElementById('selfBad').onclick=()=>markWritten(false);f.scrollIntoView({behavior:'smooth',block:'nearest'});}
function markWritten(ok){const q=questions[index];if(results.length>index)return;results.push({q,value:draft,ok,self:true});document.getElementById('writtenAnswer').classList.add(ok?'correct':'wrong');const f=document.getElementById('feedback');f.className='feedback '+(ok?'good':'bad');f.querySelector('.verdict').textContent=ok?'✓ Отмечено при самопроверке':'✕ Нужно повторить';f.querySelectorAll('.self-actions button').forEach(b=>b.disabled=true);const good=results.filter(r=>r.ok).length;app.querySelectorAll('.stat b')[0].textContent=good;app.querySelectorAll('.stat b')[1].textContent=results.length-good;app.querySelectorAll('.stat b')[2].textContent=questions.length-results.length;app.querySelector('.fill').style.width=results.length/questions.length*100+'%';app.querySelector('[role="progressbar"]').setAttribute('aria-valuenow',results.length);app.querySelector('.topline .muted').textContent=Math.round(results.length/questions.length*100)+'%';const b=document.getElementById('check');b.disabled=false;b.textContent=index===questions.length-1?'Посмотреть результат':'Следующий вопрос →';b.onclick=next;}
function next(){if(!locked)return;if(index===questions.length-1){finish();return;}index++;prepare();render();scrollToTop();}
function finish(){const good=results.filter(r=>r.ok).length,total=questions.length,pct=Math.round(good/total*100),grade=pct>=90?5:pct>=75?4:pct>=60?3:2;
 app.innerHTML=`<section class="card result-screen"><span class="type">${escapeHTML(selectedTest.title)}</span><div class="result"><span class="pill">Тест завершён</span><h2>Результат</h2><h1>${good}<span> / ${total}</span></h1><span class="grade">Учебная оценка ${grade}</span><p class="note">Автопроверка: ${results.filter(r=>!r.self).length} · Самопроверка: ${results.filter(r=>r.self).length}</p></div><div class="stats"><div class="stat good"><b>${good}</b>Правильных</div><div class="stat bad"><b>${total-good}</b>Ошибок</div><div class="stat"><b>${pct}%</b>Результат</div></div><p class="note" style="text-align:center">90–100% — 5 · 75–89% — 4<br>60–74% — 3 · меньше 60% — 2</p><div class="result-actions"><button id="review">Посмотреть ошибки (${total-good})</button><button class="primary" id="restart">Пройти заново</button><button id="toTests">Выбрать другой тест</button></div></section>`;document.getElementById('review').onclick=review;document.getElementById('restart').onclick=start;document.getElementById('toTests').onclick=backToTests;scrollToTop();}
function review(){const errors=results.filter(r=>!r.ok);app.innerHTML=`<div class="review-head"><h2>Разбор ошибок</h2><button id="back">К результатам</button></div>${errors.length?'':`<div class="card mistake"><h3>Все ответы правильные ✓</h3><p class="muted">Ошибок для разбора нет.</p></div>`}${errors.map((r,i)=>`<article class="card mistake"><span class="pill">Ошибка ${i+1} из ${errors.length}</span><h3>${escapeHTML(r.q.q)}</h3>${r.q.bodyHtml?`<div class="rich-material">${r.q.bodyHtml}</div>`:''}${r.q.options&&r.q.type!=='match'?`<div class="review-options">${r.q.options.map(o=>`<p>${escapeHTML(o.label)}</p>`).join('')}</div>`:''}${r.q.context?`<div class="context">${escapeHTML(r.q.context)}</div>`:''}${mapHTML(r.q)}<p class="user-answer"><b>Ваш ответ:</b><br>${escapeHTML(answerText(r.q,r.value))}</p><p class="right-answer"><b>Правильный ответ:</b><br>${escapeHTML(correctText(r.q))}</p><p>${escapeHTML(r.q.ex)}</p><p class="source">${escapeHTML(sourceHTML(r.q))}</p></article>`).join('')}`;document.getElementById('back').onclick=finish;app.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>showMap(b.dataset.map));scrollToTop();}
document.getElementById('closeZoom').onclick=()=>{const d=document.getElementById('zoom');if(d.close)d.close();else d.removeAttribute('open');};
document.getElementById('zoom').onclick=e=>{if(e.target===e.currentTarget)e.currentTarget.close();};
// Первый порядок создаётся при загрузке; при старте и повторном прохождении создаётся новый.
document.getElementById('homeButton').onclick=home;
home();


const lightbox=document.getElementById('imageLightbox'),lightboxImage=document.getElementById('lightboxImage');document.addEventListener('click',e=>{if(e.target.matches('.question-illustration')){lightboxImage.src=e.target.src;lightboxImage.alt=e.target.alt;lightboxImage.className='';lightbox.showModal();}else if(e.target===lightboxImage)lightboxImage.classList.toggle('expanded');});document.getElementById('closeLightbox').onclick=()=>lightbox.close();

window.EGE_READY=true;
